package com.mhtextractor.uicore;

import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

/** GUI-only process lock, held until JVM termination; the lock file is never deleted. */
public final class SingleInstanceLock {
    // A strong reference keeps both the lock and its channel alive for the JVM lifetime.
    private static FileLock heldLock;

    private SingleInstanceLock() {}

    public static synchronized boolean tryAcquire() throws IOException {
        if (heldLock != null) return true;
        Path file = Path.of("logs", "app.lock");
        Files.createDirectories(file.getParent());
        FileChannel channel = FileChannel.open(file, StandardOpenOption.CREATE, StandardOpenOption.WRITE);
        try {
            heldLock = channel.tryLock();
            if (heldLock != null) return true;
        } catch (OverlappingFileLockException alreadyHeld) {
            return false;
        } finally {
            // Never close a successfully locked channel, including during GUI shutdown.
            if (heldLock == null) channel.close();
        }
        return false;
    }
}
package com.mhtextractor.gui.component;

import atlantafx.base.theme.NordLight;
import com.mhtextractor.app.Texts;
import javafx.animation.PauseTransition;
import javafx.application.Application;
import javafx.application.Platform;
import javafx.scene.Scene;
import javafx.scene.layout.StackPane;
import javafx.stage.Stage;
import javafx.util.Duration;
import lombok.extern.slf4j.Slf4j;

/** A short application notification before a duplicate GUI process exits. */
@Slf4j
public final class SingleInstanceNotice {
    private SingleInstanceNotice() {}

    public static void show(Stage stage) {
        Application.setUserAgentStylesheet(new NordLight().getUserAgentStylesheet());
        StackPane shell = new StackPane();
        Scene scene = new Scene(shell, 480, 180);
        NotificationHost.install(scene, shell);
        stage.setTitle(Texts.get("app.title"));
        stage.setScene(scene);
        stage.setResizable(false);
        stage.show();
        NotificationHost.toastWarning(shell, Texts.get("app.alreadyRunning"));
        log.warn(Texts.msg("log.app.alreadyRunning"));
        PauseTransition exitDelay = new PauseTransition(Duration.seconds(3));
        exitDelay.setOnFinished(_ -> Platform.exit());
        exitDelay.play();
    }
}

